definition:
CREATE OR REPLACE FUNCTION public.create_hold(p_loc text, p_date date, p_start integer, p_duration integer, p_rooms integer, p_token text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if p_duration not in (50, 60, 80, 90) then return 'invalid'; end if;
  if p_start < 690 or (p_start + p_duration) > 1380 then return 'closed'; end if;
  if p_date < current_date or p_date > current_date + 30 then return 'baddate'; end if;
  if p_rooms < 1 or p_rooms > 30 then return 'invalid'; end if;

  delete from bookings where kind = 'hold' and expires_at < now();

  for n in 1..p_rooms loop
    begin
      insert into bookings(kind, loc_id, date, start_min, end_min,
                           duration, room_no, token, expires_at)
      values('hold', p_loc, p_date, p_start, p_start + p_duration,
             p_duration, n, p_token, now() + interval '7 minutes');
      return 'ok';
    exception when exclusion_violation then
      continue;   -- that room is busy, try the next one
    end;
  end loop;
  return 'full';
end $function$

CREATE OR REPLACE FUNCTION public.trg_therapist_day_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare n int;
begin
    select count(*) into n from public.therapist_days
     where loc_id = new.loc_id and date = new.date;
    if n >= 20 then
        raise exception 'Limit reached: 20 therapists per centre per day';
    end if;
    new.seq := n + 1;
    return new;
end $function$

CREATE OR REPLACE FUNCTION public.assign_therapist(p_booking_id uuid, p_therapist_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b record; d record;
begin
    select * into b from bookings where id = p_booking_id;
    if not found then return 'no_booking'; end if;

    if p_therapist_id is null then
        update bookings set therapist_id = null, therapist_name = null where id = p_booking_id;
        return 'ok';
    end if;

    select td.arrival_min, td.shift_end_min, td.on_leave, t.name into d
      from therapist_days td join therapists t on t.id = td.therapist_id
     where td.therapist_id = p_therapist_id and td.date = b.date and td.loc_id = b.loc_id;
    if not found then return 'not_registered'; end if;

    if d.on_leave                  then return 'on_leave';   end if;
    if b.start_min < d.arrival_min then return 'not_arrived'; end if;
    if d.shift_end_min is not null and b.end_min > d.shift_end_min then return 'shift_ended'; end if;

    update bookings set therapist_id = p_therapist_id, therapist_name = d.name
     where id = p_booking_id;
    return 'ok';
exception when exclusion_violation then
    return 'busy';
end $function$

CREATE OR REPLACE FUNCTION public.end_shift(p_day_id uuid, p_force boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d record; m int; c int; ist timestamp;
begin
    select * into d from therapist_days where id = p_day_id;
    if not found then return 'not_found'; end if;

    ist := now() at time zone 'Asia/Kolkata';
    if d.date <> ist::date then return 'not_today'; end if;

    m := extract(hour from ist)::int * 60 + extract(minute from ist)::int;
    if m <= d.arrival_min then return 'before_arrival'; end if;

    select count(*) into c from bookings b
     where b.therapist_id = d.therapist_id and b.date = d.date
       and b.kind = 'booking' and b.status = 'confirmed' and b.end_min > m;
    if c > 0 and not p_force then return 'has_sessions:' || c; end if;

    update therapist_days set shift_end_min = m where id = p_day_id;
    return 'ok:' || m;
end $function$
